@Override public void generateGraph(Graph<V,E> target, Map<String,V> resultMap){
    try {
        // Collect vertices from resultMap into two partitions based on key prefix
        List<V> left = new ArrayList<>();
        List<V> right = new ArrayList<>();
        for (Map.Entry<String,V> entry : resultMap.entrySet()) {
            String key = entry.getKey();
            if (key != null && key.startsWith("L")) {
                left.add(entry.getValue());
            } else if (key != null && key.startsWith("R")) {
                right.add(entry.getValue());
            }
        }
        // If no explicit prefixes, split the set approximately in half
        if (left.isEmpty() && right.isEmpty()) {
            Iterator<V> it = resultMap.values().iterator();
            int count = 0;
            while (it.hasNext()) {
                V v = it.next();
                if (count % 2 == 0) left.add(v);
                else right.add(v);
                count++;
            }
        }
        // Add all vertices to the target graph
        for (V v : left) {
            target.addVertex(v);
        }
        for (V v : right) {
            target.addVertex(v);
        }
        // Create all cross edges to form a complete bipartite graph
        for (V lv : left) {
            for (V rv : right) {
                target.addEdge(lv, rv);
            }
        }
    } catch (Exception e) {
        // Log or handle exception as appropriate
        System.err.println("Error generating complete bipartite graph: " + e.getMessage());
    }
}

