protected List<TimeRange> buildTimeRanges(long start, long end) {
    List<TimeRange> ranges = new ArrayList<>();
    if (start >= end) {
        return ranges;
    }
    long maxDuration = FETCH_DATA_DURATION;
    if (maxDuration <= 0) {
        // If duration is non-positive just add the whole range once
        ranges.add(new TimeRange(start, end));
        return ranges;
    }
    long current = start;
    while (current < end) {
        long next = current + maxDuration;
        long rangeEnd = next < 0 || next > end ? end : next; // handle overflow
        ranges.add(new TimeRange(current, rangeEnd));
        current = rangeEnd;
    }
    return ranges;
}

