void removeFromTreeEdgeList() {
    // Unlink this edge from the source node's edge list
    if (prevSrcEdge != null) {
        prevSrcEdge.nextSrcEdge = nextSrcEdge;
    }
    if (nextSrcEdge != null) {
        nextSrcEdge.prevSrcEdge = prevSrcEdge;
    }

    // Unlink this edge from the destination node's edge list
    if (prevDestEdge != null) {
        prevDestEdge.nextDestEdge = nextDestEdge;
    }
    if (nextDestEdge != null) {
        nextDestEdge.prevDestEdge = prevDestEdge;
    }

    // Null out all back references to help GC
    prevSrcEdge = null;
    nextSrcEdge = null;
    prevDestEdge = null;
    nextDestEdge = null;
}

public static String findAndSubst(String key, Properties props) {
    if (props == null || key == null) {
        return null;
