    return ignoreCase ? tail.equalsIgnoreCase(suffix) : tail.equals(suffix);
}

public static List<PathSegmentImpl> decodePath(URI u, boolean decode){
    List<PathSegmentImpl> result = new ArrayList<>();
    if (u == null) {
        return result;
    }
    String rawPath = u.getRawPath();
    if (rawPath == null || rawPath.isEmpty()) {
        return result;
    }
    // Remove leading slash for absolute paths
    if (rawPath.charAt(0) == '/') {
        rawPath = rawPath.substring(1);
    }
    // Split into segments on '/'
    String[] segments = rawPath.split("/");
    for (String segment : segments) {
        if (segment.isEmpty()) {
            continue;
        }
        String decodedSegment = segment;
        if (decode) {
            try {
                decodedSegment = URLDecoder.decode(segment, StandardCharsets.UTF_8.name());
            } catch (UnsupportedEncodingException e) {
                throw new RuntimeException(e);
            }
        }
        // Construct PathSegmentImpl with decoded and encoded values
        result.add(new PathSegmentImpl(decodedSegment, segment));
    }
    return result;
}

