@Override protected Object convertToType(final Class<?> type, final Object value) throws Exception {
    // Ensure the target type is Character or primitive char
    if (type == null) {
        throw new Exception("Target type is null");
    }
    if (!Character.class.equals(type) && !char.class.equals(type)) {
        throw new Exception("Target type is not Character");
    }

    // Allow null values to map to null
    if (value == null) {
        return null;
    }

    // If already a Character instance, return it directly
    if (value instanceof Character) {
        return value;
    }

    // Handle CharSequence (String, StringBuilder, etc.)
    if (value instanceof CharSequence) {
        CharSequence cs = (CharSequence) value;
        if (cs.length() != 1) {
            throw new Exception("Cannot convert CharSequence to Character: length != 1");
        }
        return cs.charAt(0);
    }

    // Handle numeric values by casting to char
    if (value instanceof Number) {
        int intVal = ((Number) value).intValue();
        return (char) intVal;
    }

    // Fallback: convert to string and ensure single character
    String str = value.toString();
    if (str.length() != 1) {
        throw new Exception("Cannot convert to Character: string size != 1");
    }
    return str.charAt(0);
}

