private Map<String,Object> buildContent(JsonObject jsonObject){
    Map<String,Object> content = new LinkedHashMap<>();
    if (jsonObject == null) {
        return content;
    }
    try {
        for (Map.Entry<String, JsonElement> entry : jsonObject.entrySet()) {
            String key = entry.getKey();
            JsonElement element = entry.getValue();
            if (element == null) {
                continue;
            }
            Object value;
            if (key.equals("ats")) {
                // Preserve the JsonElement itself for 'ats'
                value = element;
            } else if (element.isJsonPrimitive()) {
                JsonPrimitive prim = element.getAsJsonPrimitive();
                if (prim.isNumber()) {
                    value = prim.getAsNumber();
                } else if (prim.isBoolean()) {
                    value = prim.getAsBoolean();
                } else {
                    value = prim.getAsString();
                }
            } else if (element.isJsonArray()) {
                value = element.getAsJsonArray();
            } else if (element.isJsonObject()) {
                value = element.getAsJsonObject();
            } else {
                value = element.toString();
            }
            content.put(key, value);
        }
    } catch (Exception e) {
        // Ideally log the exception. Return the content collected so far.
        return new LinkedHashMap<>();
    }
    return content;
}

