        throw new IllegalArgumentException("bytecodeOffset out of bounds: " + bytecodeOffset);
    }
    Label label = labels[bytecodeOffset];
    if (label == null) {
        try {
            // Try to create a new label with the offset if such constructor exists
            label = new Label(bytecodeOffset);
        } catch (NoSuchMethodError | InstantiationException | IllegalAccessException | java.lang.reflect.InvocationTargetException e) {
