private OuterFaceCirculator selectOnOuterFace(Predicate<Node> predicate, Node start, Node stop, int dir){
    if (predicate == null) {
        throw new IllegalArgumentException("predicate must not be null");
    }
    if (start == null) {
        throw new IllegalArgumentException("start node must not be null");
    }
    if (stop == null) {
        throw new IllegalArgumentException("stop node must not be null");
    }

    // If the start node already satisfies the predicate, immediately return it.
    if (predicate.test(start)) {
        return new OuterFaceCirculator(start, dir);
    }

    Node current = start;
    // Use a simple counter to avoid infinite loops in malformed graphs.
    // In a proper planar embedding the traversal will terminate at 'stop'.
    int maxIterations = Integer.MAX_VALUE; // effectively no limit
    while (current != stop && maxIterations-- > 0) {
        Node next = current.getNextOuterFace(dir);
        if (next == null) {
            // If we can't proceed further, break to avoid NPE.
            break;
        }
        current = next;
        if (predicate.test(current)) {
            return new OuterFaceCirculator(current, dir);
        }
    }

    // Either we reached 'stop' or no node satisfied the predicate before that.
    return new OuterFaceCirculator(stop, dir);
}

