    // Retrieve the list of sharding key indices for the specified model.
    // This could be obtained from a metadata registry or mapping.
    List<Integer> indices = getShardingKeyIndices(modelName);

    // If there are no sharding keys defined, nothing to validate.
    if (indices == null || indices.isEmpty()) {
        return;
    }

    // Sort the indices to ensure order before validation.
    indices.sort(Integer::compareTo);

    // Verify that the indices are contiguous, starting from 0.
    for (int i = 0; i < indices.size(); i++) {
        Integer expected = i;
        Integer actual = indices.get(i);
        if (!expected.equals(actual)) {
            throw new IllegalStateException(
                "Sharding key indices for model '" + modelName +
                "' are not continuous. Expected " + expected + " but found " + actual +
                " in indices " + indices);
        }
    }
}

