public int compare(Object aObj1, Object aObj2){
    if (aObj1 == aObj2) {
        return 0;
    }
    if (aObj1 == null) {
        return -1;
    }
    if (aObj2 == null) {
        return 1;
    }
    if (!(aObj1 instanceof byte[])) {
        throw new ClassCastException("Expected byte[] but got " + aObj1.getClass().getName());
    }
    if (!(aObj2 instanceof byte[])) {
        throw new ClassCastException("Expected byte[] but got " + aObj2.getClass().getName());
    }
    byte[] b1 = (byte[]) aObj1;
    byte[] b2 = (byte[]) aObj2;
    int len1 = b1.length;
    int len2 = b2.length;
    int minLen = Math.min(len1, len2);
    for (int i = 0; i < minLen; i++) {
        int diff = b1[i] - b2[i];
        if (diff != 0) {
            return diff;
        }
    }
    return len1 - len2; // shorter array is considered smaller
}

