private void reload(List<Set<Integer>> bucketsByLabel,List<Integer> labels,int minLabel){
    if (bucketsByLabel == null || labels == null) {
        return;
    }
    if (minLabel < 0 || minLabel >= bucketsByLabel.size()) {
        return;
    }
    Set<Integer> src = bucketsByLabel.get(minLabel);
    if (src == null || src.isEmpty()) {
        return;
    }
    // Ensure bucket for label 0 exists
    Set<Integer> dest = bucketsByLabel.get(0);
    if (dest == null) {
        dest = new java.util.HashSet<>();
        bucketsByLabel.set(0, dest);
    }
    // Move vertices from minLabel to 0 and update labels
    for (Integer v : src) {
        if (v != null && v >= 0 && v < labels.size()) {
            labels.set(v, 0);
        }
        dest.add(v);
    }
    // Clear the original bucket
    src.clear();
}

