        }
    }
    return true;
}

public void abbreviate(final int nameStart, final StringBuffer buf) {
    // Validate the buffer
    if (buf == null) {
        throw new NullPointerException("The buffer to append to cannot be null.");
    }
    // Assume the class has a field named 'name' that stores the full name
    // If no such field exists, this method will not compile in that context.
    final String fullName = this.name;
    if (fullName == null || fullName.isEmpty()) {
        return; // nothing to abbreviate
    }
    // Normalise the starting index
    int start = nameStart;
    if (start < 0) {
        start = 0;
    }
    if (start >= fullName.length()) {
        return; // starting beyond the string, nothing to add
    }
    // Extract the part of the name to abbreviate
    String toAbbreviate = fullName.substring(start).trim();
    if (toAbbreviate.isEmpty()) {
        return;
    }
    // Split into words on whitespace
    String[] words = toAbbreviate.split("\\s+");
    for (int i = 0; i < words.length; i++) {
        String word = words[i];
        if (!word.isEmpty()) {
            // Append the first character of each word and a period
            buf.append(word.charAt(0));
            if (i < words.length - 1) {
                buf.append('.');
            }
        }
    }
}

public static Type resolveBound(TypeVariable<?> typeVariable) {
    try {
        if (typeVariable == null) {
            return Unknown.class;
        }
        Type[] bounds = typeVariable.getBounds();
        if (bounds != null && bounds.length > 0 && bounds[0] != null) {
            return bounds[0];
        }
        return Unknown.class;
    } catch (Exception e) {
        // Fallback in case of any unexpected errors
        return Unknown.class;
    }
}

private static <V,E> boolean isClique(Graph<V,E> graph, Set<V> vertices) {
    for (V v1 : vertices) {
        for (V v2 : vertices) {
            if (!v1.equals(v2) && graph.getEdge(v1, v2) == null) {
