    }
    return true;
}

private List<Integer> computeLowerBounds(List<K> keys){
    if (keys == null) {
        throw new IllegalArgumentException("keys list cannot be null");
    }
    List<Integer> bounds = new ArrayList<>(keys.size());
    List<K> sorted = new ArrayList<>(keys);
    try {
        Collections.sort(sorted);
    } catch (ClassCastException e) {
        throw new IllegalArgumentException("All keys must be Comparable", e);
    }
    for (K key : keys) {
        int bound = -1;
        for (int i = 0; i < sorted.size(); i++) {
            @SuppressWarnings("unchecked")
            Comparable<? super K> comp = (Comparable<? super K>) sorted.get(i);
            if (comp.compareTo(key) <= 0) {
                bound = i;
            } else {
                break;
            }
        }
        bounds.add(bound);
    }
    return bounds;
}

private void pop(final String descriptor){
    if (descriptor == null || descriptor.isEmpty()){
        return;
    }
    int count = 0;
    int i = 0;
    if (descriptor.charAt(0) == '('){
        i = 1;
        while (descriptor.charAt(i) != ')'){
            char c = descriptor.charAt(i);
            if (c == 'L'){
                i = descriptor.indexOf(';', i) + 1;
            } else if (c == '['){
                do{
                    i++;
                }while (descriptor.charAt(i) == '[');
                if (descriptor.charAt(i) == 'L'){
                    i = descriptor.indexOf(';', i) + 1;
                } else {
                    i++;
                }
            } else {
                i++;
            }
            count++;
        }
    } else {
        count = 1;
    }
    pos -= count;
}

