private List<Integer> computeUpperBounds(List<K> keys){
    // Handle null or empty input gracefully
    if (keys == null || keys.isEmpty()){
        return new ArrayList<Integer>();
    }
    // Attempt to extract integer values from the list. If any element is not an Integer,
    // it is ignored for computing the upper bound.
    int maxValue = Integer.MIN_VALUE;
    boolean hasInteger = false;
    for (K key : keys){
        if (key instanceof Integer){
            int val = (Integer) key;
            hasInteger = true;
            if (val > maxValue){
                maxValue = val;
            }
        }
    }
    // If no integer values were found, return an empty list.
    if (!hasInteger){
        return new ArrayList<Integer>();
    }
    // Construct the result list, repeating the computed upper bound for each original key.
    List<Integer> result = new ArrayList<Integer>(keys.size());
    for (int i = 0; i < keys.size(); i++){
        result.add(maxValue);
    }
    return result;
}

public static String encodeTemplateNames(String s){
    if (s == null) {
        return null;
    }
    StringBuilder sb = new StringBuilder(s.length());
    for (int i = 0; i < s.length(); i++) {
        char c = s.charAt(i);
        if (c == '{') {
            sb.append("%7B");
        } else if (c == '}') {
            sb.append("%7D");
        } else {
            sb.append(c);
        }
    }
    return sb.toString();
}

