public static String applyRelativePath(String path, String relativePath) {
    if (path == null) {
        return relativePath == null ? null : relativePath;
    }
    if (relativePath == null || relativePath.isEmpty()) {
        // Return original path if relative path is empty or null
        return path;
    }

    // Split the base path and create a stack of components
    String[] baseParts = path.split("/", -1);
    java.util.ArrayDeque<String> stack = new java.util.ArrayDeque<>();
    for (String part : baseParts) {
        stack.addLast(part);
    }

    // Split the relative path and apply each component
    String[] relParts = relativePath.split("/", -1);
    for (String part : relParts) {
        if (part.isEmpty() || part.equals(".")) {
            // No effect on stack
            continue;
        }
        if (part.equals("..")) {
            if (!stack.isEmpty() && !stack.peekLast().isEmpty()) {
                stack.removeLast();
            }
        } else {
            stack.addLast(part);
        }
    }

    String result = String.join("/", stack);
    // Handle special cases: root or empty result
    if (result.isEmpty()) {
        // If the original path starts with '/', preserve root
        return path.startsWith("/") ? "/" : ".";
    }
    return result;
}

