static String[] toNoNullStringArray(Object[] array){
    if (array == null) {
        return null;
    }
    int nullCount = 0;
    for (Object o : array) {
        if (o == null) {
            nullCount++;
        }
    }
    if (nullCount == 0) {
        // The caller expects a String[]; cast is safe if the array is actually a String[]
        return (String[]) array;
    }
    String[] result = new String[array.length - nullCount];
    int idx = 0;
    for (Object o : array) {
        if (o != null) {
            result[idx++] = (String) o;
        }
    }
    return result;
}

public static int indexOfExtension(String filename){
    if (filename == null){
        return -1;
    }
    int lastDot = filename.lastIndexOf('.');
    if (lastDot == -1){
        return -1;
    }
    int lastSep = -1;
    int slash = filename.lastIndexOf('/');
    if (slash > lastSep){
        lastSep = slash;
    }
    int backslash = filename.lastIndexOf('\\');
    if (backslash > lastSep){
        lastSep = backslash;
    }
    return (lastDot > lastSep) ? lastDot : -1;
}

public boolean isExpired(long timestamp,long expiredThreshold){
    if (timestamp <= 0) {
        return false;
    }
    if (expiredThreshold <= 0) {
        return false;
    }
    long now = System.currentTimeMillis();
    long diff = now - timestamp;
    return diff > expiredThreshold;
}

Edge edgeToNext() {
    try {
        if (_edges == null) {
            return null;
        }
        Node from = _currentNode;
        Node to = _nextNode;
        if (from == null || to == null) {
            return null;
        }
        // Resolve virtual nodes if the node reports being virtual
        if (from.isVirtual()) {
            from = from.getRealNode();
        }
        if (to.isVirtual()) {
            to = to.getRealNode();
        }
        for (Edge e : _edges) {
            if (e.getFrom() == from && e.getTo() == to) {
                return e;
            }
        }
        return null;
    } catch (Exception e) {
        return null;
    }
}

public static boolean substringMatch(CharSequence str,int index,CharSequence substring){
    if(str==null || substring==null) return false;
    int lenStr = str.length();
    int lenSub = substring.length();
    if(index<0 || index>lenStr) return false;
    if(lenSub==0){
        return index==lenStr || index<=lenStr;
    }
    if(index+lenSub>lenStr) return false;
    for(int i=0;i<lenSub;i++){
        if(str.charAt(index+i)!=substring.charAt(i)) return false;
    }
    return true;
}

