private void checkIfPackedField() throws IOException {
    // Determine the wire type from the current tag
    int wireType = (this.tag) & 0x7;
    // Check if the current field is defined as packed and is encoded as a length‑delimited field
    if (wireType == com.google.protobuf.WireFormat.WIRETYPE_LENGTH_DELIMITED &&
        this.field.getDescriptor().isRepeated() &&
        this.field.getDescriptor().isPacked()) {
        // Update internal state to indicate that packed fields are being read
        this.inPackedField = true;
    }
}

